<?php
declare(strict_types=1);
require dirname(__DIR__) . '/private/bootstrap.php';
$token = (string)($_GET['e'] ?? ''); $event = event_by_token($token);
if (!$event || !(int)$event['activo']) { http_response_code(404); $closed = true; } else { $closed = false; }
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $event ? e($event['nombre']) : 'Evento no disponible' ?> · EventQR</title><link rel="stylesheet" href="/assets/style.css"></head><body class="guest"><main class="card guest-card"><div class="brand">Event<span>QR</span></div><?php if ($closed): ?><h1>Evento no disponible</h1><p>Este enlace no existe o el evento fue cerrado.</p><?php else: ?><h1><?= e($event['nombre']) ?></h1><p class="date"><?= e(date('d/m/Y', strtotime($event['fecha']))) ?></p><form id="upload-form" data-token="<?= e($token) ?>"><input id="photos" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.jpg,.jpeg,.png,.webp,.heic,.heif" multiple hidden><button class="button secondary" type="button" id="select">Seleccionar fotografías</button><p id="selection" class="muted">No has seleccionado fotografías</p><button class="button primary" id="send" type="submit" disabled>Subir fotografías</button><div class="progress-wrap" hidden><progress id="progress" max="100" value="0"></progress><span id="progress-label">0%</span></div><p id="message" class="message" aria-live="polite"></p></form><?php endif; ?></main><?php if (!$closed): ?><script src="/assets/guest.js" defer></script><?php endif; ?></body></html>
